var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("Packaging");
var roots = scene.GetRootGameObjects();
Sim.SubGames.Packaging.PackagingFeedback fb = null;
foreach (var r in roots) { fb = r.GetComponentInChildren<Sim.SubGames.Packaging.PackagingFeedback>(true); if (fb != null) break; }
if (fb == null) { Debug.LogError("fb null"); return; }
var so = new UnityEditor.SerializedObject(fb);
so.Update();
string Read(string p) { var v = so.FindProperty(p).objectReferenceValue; return v != null ? v.name : "NULL"; }
Debug.Log("resultPanel=" + Read("resultPanel") + " rating=" + Read("ratingLabel") + " score=" + Read("scoreLabel"));
